<?php require '../includes/layout.php'; require_role(['admin']); $d=db();$q=trim($_GET['q']??'');$status=$_GET['status']??'';$payment=$_GET['payment']??'';
$where=[];$params=[];if($q){$where[]='(o.order_no LIKE ? OR u.name LIKE ? OR o.notes LIKE ?)';$params[]="%$q%";$params[]="%$q%";$params[]="%$q%";}if(in_array($status,['pending','confirmed','preparing','ready','completed','cancelled'],true)){$where[]='o.status=?';$params[]=$status;}if(in_array($payment,['unpaid','paid'],true)){$where[]='o.payment_status=?';$params[]=$payment;}
$sql='SELECT o.*,u.name customer FROM orders o JOIN users u ON u.id=o.customer_id'.($where?' WHERE '.implode(' AND ',$where):'').' ORDER BY o.id DESC LIMIT 200';$s=$d->prepare($sql);$s->execute($params);$orders=$s->fetchAll();
head('Orders');?><div class="mb-4"><p class="text-xs font-semibold uppercase tracking-[.2em] text-mute">Order management</p><h1 class="text-2xl font-semibold mt-1">Orders</h1><p class="text-sm text-mute mt-1">Search and filter the latest customer orders.</p></div>
<form method="get" class="<?=card('p-4 mb-5 grid gap-3 sm:grid-cols-[1fr_10rem_10rem_auto] items-end')?>"><label class="text-sm">Search<input class="<?=INP?> mt-1" name="q" value="<?=e($q)?>" placeholder="Order ID or customer"></label><label class="text-sm">Status<select class="<?=INP?> mt-1" name="status"><option value="">All statuses</option><?php foreach(['pending','confirmed','preparing','ready','completed','cancelled'] as $value):?><option value="<?=$value?>" <?=$status===$value?'selected':''?>><?=ucfirst($value)?></option><?php endforeach?></select></label><label class="text-sm">Payment<select class="<?=INP?> mt-1" name="payment"><option value="">All payments</option><option value="unpaid" <?=$payment==='unpaid'?'selected':''?>>Unpaid</option><option value="paid" <?=$payment==='paid'?'selected':''?>>Paid</option></select></label><button class="<?=BTN?>">Filter</button></form>
<div class="<?=card('overflow-x-auto')?>"><table class="w-full min-w-[54rem] text-sm"><thead><tr class="text-left text-xs uppercase tracking-wide text-mute"><th class="p-3">Order</th><th>Customer</th><th>Date</th><th>Total</th><th>Status</th><th>Payment</th><th class="p-3 text-right">Receipt</th></tr></thead><tbody><?php foreach($orders as $o):?><tr class="border-t border-line"><td class="p-3 font-semibold"><?=e($o['order_no'])?></td><td><?=e($o['customer'])?></td><td><?=date('M j, Y g:i A',strtotime($o['created_at']))?></td><td><?=money($o['total'])?></td><td><span class="rounded-full bg-soft px-2 py-1 text-xs"><?=ucfirst(e($o['status']))?></span></td><td><?=ucfirst(e($o['payment_status']))?></td><td class="p-3 text-right"><a class="text-[#C978A1] underline" href="<?=BASE?>/receipt.php?order=<?=rawurlencode($o['order_no'])?>">Print</a></td></tr><?php endforeach?><?php if(!$orders):?><tr><td class="p-8 text-center text-mute" colspan="7">No orders found.</td></tr><?php endif?></tbody></table></div><?php foot();
